starterCode:
LOAD spatial;

-- Reproject each landmark from WGS84 to Web Mercator (EPSG:3857).
-- Return: name, merc_x, merc_y (rounded to whole metres) ordered by name

setup:
CREATE TABLE landmarks AS SELECT * FROM (VALUES
  ('Statue of Liberty', 40.6892, -74.0445),
  ('Empire State',      40.7484, -73.9857),
  ('Brooklyn Bridge',   40.7061, -73.9969)
) t(name, lat, lon);

solution:
LOAD spatial;

SELECT name,
       ROUND(ST_X(ST_Transform(ST_Point(lat, lon), 'EPSG:4326', 'EPSG:3857'))) AS merc_x,
       ROUND(ST_Y(ST_Transform(ST_Point(lat, lon), 'EPSG:4326', 'EPSG:3857'))) AS merc_y
FROM landmarks
ORDER BY name;
